import UTIF from"utif";const MIME_TYPE="image/tiff";export default()=>({mime:{[MIME_TYPE]:["tiff","tif"]},constants:{MIME_TIFF:MIME_TYPE},decoders:{[MIME_TYPE]:t=>{const e=UTIF.decode(t),o=e[0];UTIF.decodeImages(t,e);const f=UTIF.toRGBA8(o);return{data:Buffer.from(f),width:o.t256[0],height:o.t257[0]}}},encoders:{[MIME_TYPE]:t=>{const e=UTIF.encodeImage(t.bitmap.data,t.bitmap.width,t.bitmap.height);return Buffer.from(e)}}});